<?php
if(PHP_SAPI!=='cli')exit;
require __DIR__.'/../../api/db.php';
$db=Database::getConnection();$name=getenv('NSC_UNICODE_QA_DATABASE')?:'nsc_unicode_qa_'.bin2hex(random_bytes(5));if(!preg_match('/^nsc_unicode_qa_[a-z0-9_]+$/D',$name))throw new RuntimeException('Invalid isolated database name');$db->exec("CREATE DATABASE IF NOT EXISTS `$name` CHARACTER SET latin1 COLLATE latin1_swedish_ci");
function runUnicodeMigration(string $name):void{$env=getenv();$env['DB_NAME']=$name;$p=proc_open(['php',__DIR__.'/../../scripts/server/migrate.php'],[1=>['pipe','w'],2=>['pipe','w']],$pipes,null,$env);$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);if(proc_close($p)!==0||!str_contains($out,'Migration completed'))throw new RuntimeException('Unicode migration failed: '.$err);}
try{
 runUnicodeMigration($name);$qa=new PDO('mysql:host='.DB_HOST.';port='.DB_PORT.';dbname='.$name.';charset=utf8mb4',DB_USER,DB_PASS,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
 $security=['schema_migrations','office7_control','public_page','auth_rate_limits','uploaded_files','financial_requests','password_resets','tenant_workspaces','workspace_revisions'];
 foreach($security as $table){$s=$qa->prepare('SELECT engine,table_collation FROM information_schema.tables WHERE table_schema=:d AND table_name=:t');$s->execute(['d'=>$name,'t'=>$table]);$m=$s->fetch(PDO::FETCH_ASSOC);if(strtolower($m['engine'])!=='innodb'||!str_starts_with($m['table_collation'],'utf8mb4_'))throw new RuntimeException('Bad security table '.$table);}
 $json=json_encode(['name'=>'قرضدار، سیخ گول، سمنت — پښتو ژبه 🏗️'],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);$s=$qa->prepare('INSERT INTO tenant_workspaces(tenant_id,document) VALUES(:id,:doc)');$s->execute(['id'=>'unicode-qa','doc'=>$json]);if($qa->query("SELECT document FROM tenant_workspaces WHERE tenant_id='unicode-qa'")->fetchColumn()!==$json)throw new RuntimeException('Multilingual JSON did not round-trip');
 $qa->exec('ALTER TABLE public_page ENGINE=MyISAM, CONVERT TO CHARACTER SET latin1');runUnicodeMigration($name);$m=$qa->query("SELECT engine,table_collation FROM information_schema.tables WHERE table_schema='$name' AND table_name='public_page'")->fetch(PDO::FETCH_ASSOC);if(strtolower($m['engine'])!=='innodb'||!str_starts_with($m['table_collation'],'utf8mb4_'))throw new RuntimeException('Upgrade did not repair existing security table');echo "UNICODE SCHEMA PASSED: latin1 host default, 9 security tables, Dari/Pashto/emoji round-trip, existing MyISAM/latin1 upgrade.\n";
}finally{$db->exec("DROP DATABASE `$name`");}
